  function read(store,key){if(!db)return Promise.resolve(store==='media'?mediaBlobs.get(key):null);return new Promise(resolve=>{try{const req=db.transaction(store).objectStore(store).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);}catch{resolve(null);}});}
