  function icon(name,{tone=null,filled=false,cls=''}={}){const c=tone||color(true),fill=filled||name==='signal'||name==='x'?c:'none',width=name==='signal'?45:24;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="24" viewBox="0 0 ${width} 24" fill="${fill}" stroke="${c}" stroke-width="${name==='signal'?0:1.7}" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.more}</svg>`.replaceAll('currentColor',c);return `<img class="xs-ui-icon ${cls}" alt="" src="data:image/svg+xml,${encodeURIComponent(svg)}"/>`;}
