  function renderLibrary(){const q=$('x-character-search').value.trim().toLowerCase();$('x-character-library').innerHTML=state.characters.filter(c=>(c.name+' '+c.handle).toLowerCase().includes(q)).map(c=>`<button type="button" class="xs-library-character ${c.id===state.selectedCharacter?'active':''}" data-character="${esc(c.id)}">${avatar(c)}<span><strong>${esc(c.name)} ${badges(c,true)}</strong><small>@${esc(c.handle)}</small></span></button>`).join('');$('x-post-library').innerHTML=state.posts.slice().reverse().map(p=>`<button type="button" class="${state.selectedPost===p.id?'active':''}" data-edit-post="${esc(p.id)}"><strong>${esc(findCharacter(p.author)?.name)} · ${esc(p.kind)}</strong><small>${esc(p.text||'Media post')}</small></button>`).join('');}
