  const charFields={name:'name',handle:'handle',bio:'bio',location:'location',link:'link',joined:'joined',following:'following',followers:'followers',relationship:'relationship',verified:'verified',private:'private','follows-you':'followsYou','followed-by':'followedBy',pinned:'pinned'};
