  function mediaGrid(p){if(!p.media.length||p.kind==='repost')return '';return `<div class="xs-media-grid count-${p.media.length} shape-${p.mediaShape}">${p.media.map(m=>`<div class="xs-media-tile">${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.type==='image'?'Photo':'Video still')}"/>`:'<div class="xs-media-empty">▧</div>'}${m.type==='video'?`<button type="button" class="xs-video-play" data-play-media="${esc(m.id)}" aria-label="Play attached video"><span>▶</span></button><span class="xs-media-duration">${esc(m.duration)}</span>`:''}</div>`).join('')}${p.sensitive?'<div class="xs-sensitive"><strong>Sensitive content</strong><span>The following media may contain sensitive material.</span><button type="button" data-show-sensitive="'+esc(p.id)+'">Show</button></div>':''}</div>`;}
