    $('x-status').hidden=!state.showStatus;$('x-status').innerHTML=`<span>${esc(state.phoneTime||'3:08')}</span><div class="xs-status-right">${icon('signal',{tone:color()})}<span class="xs-phone-battery">${state.battery}</span></div>`;
    const top=$('x-top-navigation');top.className='xs-top-navigation'+(state.view==='profile'?' profile-nav':'');top.style.top=state.view==='profile'?(state.showStatus?'48px':'12px'):'';top.innerHTML=navigation(state.view==='profile');
    const bottom=$('x-bottom-navigation');bottom.hidden=!state.showNavigation;bottom.innerHTML=['home','search','grok','bell','mail'].map((name,i)=>`<button type="button" data-bottom-nav="${name}" aria-label="${['Home timeline','Search library','Post studio','Profile notifications','Messages preview'][i]}">${icon(name,{tone:color(),filled:name==='home'})}</button>`).join('');
    let markup='';const selected=state.tab==='post'&&state.postDraft.id===state.selectedPost?state.postDraft:findPost(state.selectedPost);
