  $('x-character-search').addEventListener('input',renderLibrary);$('x-character-library').addEventListener('click',e=>{const b=e.target.closest('[data-character]');if(b)selectCharacter(b.dataset.character);});$('x-post-library').addEventListener('click',e=>{const b=e.target.closest('[data-edit-post]');if(b)selectPost(b.dataset.editPost);});
