  $('x-new-character').addEventListener('click',()=>{if(state.characters.length>=100)return notify('This project supports 100 characters.');state.characterDraft=character();state.selectedCharacter=state.characterDraft.id;state.tab='character';state.view='profile';renderAll();save();});
