  for(const [id,key] of Object.entries(charFields))$('x-character-'+id).addEventListener('input',e=>{state.characterDraft[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;syncCharacter();renderPreview();save();});
  $('x-character-form').addEventListener('submit',e=>{e.preventDefault();const c=clone(state.characterDraft);c.name=c.name.trim();c.handle=c.handle.trim().replace(/^@/,'').replace(/[^A-Za-z0-9_]/g,'');if(!c.name||!c.handle)return notify('Add a display name and username.');if(state.characters.some(x=>x.id!==c.id&&x.handle.toLowerCase()===c.handle.toLowerCase()))return notify('Give this character a unique username.');const i=state.characters.findIndex(x=>x.id===c.id);if(i>=0)state.characters[i]=c;else{if(state.characters.length>=100)return notify('This project supports 100 saved characters.');state.characters.push(c);}state.characterDraft=clone(c);state.selectedCharacter=c.id;renderAll();save();notify('Character saved. You can choose them as a post author.');});
  $('x-duplicate-character').addEventListener('click',()=>{state.characterDraft={...clone(state.characterDraft),id:uid(),name:state.characterDraft.name+' copy',handle:state.characterDraft.handle+'_copy',pinned:''};state.selectedCharacter=state.characterDraft.id;state.view='profile';renderAll();save();});
  $('x-delete-character').addEventListener('click',()=>{const id=state.characterDraft.id;if(state.posts.some(p=>p.author===id))return notify('Reassign or delete this character’s posts before deleting their profile.');if(state.characters.length<=1&&state.characters.some(c=>c.id===id))return notify('Keep at least one saved character.');if(!confirm('Delete this character?'))return;state.characters=state.characters.filter(c=>c.id!==id);selectCharacter(state.characters[0].id);});
  for(const [id,key] of Object.entries(postFields))$('x-post-'+id).addEventListener('input',e=>{state.postDraft[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='kind'||key==='author')syncPost();else $('x-text-count').textContent=`${state.postDraft.text.length.toLocaleString()} characters${state.postDraft.text.length>280?' · long post':''}`;$('x-post-draft-label').textContent='Draft';renderPreview();save();});
  $('x-poll-footer').addEventListener('input',e=>{state.postDraft.pollFooter=e.target.value;renderPreview();save();});
  function cyclic(candidate){const all=state.posts.filter(p=>p.id!==candidate.id).concat(candidate),byId=new Map(all.map(p=>[p.id,p]));let id=candidate.reference,seen=new Set([candidate.id]);while(id){if(seen.has(id))return true;seen.add(id);const p=byId.get(id);id=p&&p.kind!=='post'?p.reference:'';}return false;}
  $('x-post-form').addEventListener('submit',e=>{e.preventDefault();const p=clone(state.postDraft);if(p.kind==='post')p.reference='';if(!state.characters.some(c=>c.id===p.author))return notify('Save a character and choose them as the author.');if(p.kind!=='post'&&(!findPost(p.reference)||p.reference===p.id))return notify('Choose an existing post or reply to reference.');if(cyclic(p))return notify('That connection would create a loop. Choose another post.');if(p.kind!=='repost'&&!p.text.trim()&&!p.media.length&&!p.poll)return notify('Add text, media or a poll before saving.');const i=state.posts.findIndex(x=>x.id===p.id);if(i>=0)state.posts[i]=p;else if(state.posts.length<300)state.posts.push(p);else return notify('This project supports 300 saved posts.');state.characters.forEach(c=>{if(c.pinned===p.id&&c.id!==p.author)c.pinned='';});state.selectedPost=p.id;state.postDraft=clone(p);renderAll();save();notify('Post saved to your story.');});
  $('x-duplicate-post').addEventListener('click',()=>{state.postDraft={...clone(state.postDraft),id:uid()};state.selectedPost=state.postDraft.id;state.view='post';renderAll();save();});
  $('x-delete-post').addEventListener('click',()=>{const id=state.postDraft.id;if(!confirm('Delete this post? Replies and quotes will keep an unavailable-post placeholder.'))return;state.posts=state.posts.filter(p=>p.id!==id);state.characters.forEach(c=>{if(c.pinned===id)c.pinned='';});if(state.characterDraft.pinned===id)state.characterDraft.pinned='';newPost();});
  for(const [id,key] of [['x-view','view'],['x-theme','theme'],['x-profile-posts','profilePosts'],['x-show-status','showStatus'],['x-show-navigation','showNavigation'],['x-phone-time','phoneTime'],['x-phone-battery','battery']])$(id).addEventListener('input',e=>{state[key]=e.target.type==='checkbox'?e.target.checked:key==='battery'?Math.max(1,Math.min(100,Number(e.target.value)||1)):e.target.value;renderPreview();save();});
  $('x-profile-select').addEventListener('change',e=>selectCharacter(e.target.value));$('x-focus-post').addEventListener('change',e=>selectPost(e.target.value));
  async function resized(file,max=1400,aspect=null){const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();let sx=0,sy=0,sw=img.width,sh=img.height;if(aspect){if(sw/sh>aspect){sw=sh*aspect;sx=(img.width-sw)/2;}else{sh=sw/aspect;sy=(img.height-sh)/2;}}const scale=Math.min(1,max/Math.max(sw,sh)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(sw*scale));c.height=Math.max(1,Math.round(sh*scale));c.getContext('2d').drawImage(img,sx,sy,sw,sh,0,0,c.width,c.height);return {poster:c.toDataURL('image/jpeg',.9),blob:await new Promise(r=>c.toBlob(r,'image/jpeg',.9))};}finally{URL.revokeObjectURL(url);}}
  for(const [id,key,max,aspect] of [['x-character-avatar','avatar',400,1],['x-character-header','header',1500,3]])$(id).addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{state.characterDraft[key]=(await resized(f,max,aspect)).poster;syncCharacter();renderPreview();save();}catch{notify('Could not load that image. Try PNG, JPG or WEBP.');}e.target.value='';});
