  function videoPoster(file){return new Promise(resolve=>{const video=document.createElement('video'),url=URL.createObjectURL(file);let done=false,timer;const finish=poster=>{if(done)return;done=true;clearTimeout(timer);video.pause();video.removeAttribute('src');video.load();URL.revokeObjectURL(url);resolve(poster);};video.muted=true;video.playsInline=true;video.preload='auto';const draw=()=>{try{const c=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(video.videoWidth||640,video.videoHeight||360));c.width=Math.max(1,Math.round((video.videoWidth||640)*scale));c.height=Math.max(1,Math.round((video.videoHeight||360)*scale));c.getContext('2d').drawImage(video,0,0,c.width,c.height);finish(c.toDataURL('image/jpeg',.9));}catch{finish('');}};video.onloadeddata=()=>{try{video.currentTime=Math.min(.1,(video.duration||1)/2);}catch{draw();}};video.onseeked=draw;video.onerror=()=>finish('');timer=setTimeout(()=>finish(''),5000);video.src=url;video.load();});}
  $('x-post-media').addEventListener('change',async e=>{const files=[...e.target.files||[]],target=state.postDraft;for(const f of files){if(target.media.length>=4){notify('Each post can contain up to four media items.');break;}if(!/^(image|video)\//.test(f.type)){notify('Choose an image or video file.');continue;}if(f.size>85*1024*1024){notify('Keep each media file under 85 MB.');continue;}try{const type=f.type.startsWith('video/')?'video':'image',image=type==='image'?await resized(f):null,blob=image?image.blob:f,id=uid(),poster=image?image.poster:await videoPoster(f);await write('media',id,blob);mediaBlobs.set(id,blob);mediaUrls.set(id,URL.createObjectURL(blob));target.media.push({id,type,name:f.name,poster,duration:'0:15'});if(state.postDraft===target){renderMediaEditor();renderPreview();}save();}catch{notify('This attachment could not be stored. Try another file or save a project.');}}e.target.value='';});
  $('x-post-media-list').addEventListener('click',e=>{const remove=e.target.closest('[data-remove-media]'),move=e.target.closest('[data-move-media]');if(remove)state.postDraft.media.splice(Number(remove.dataset.removeMedia),1);else if(move){const i=Number(move.dataset.moveMedia);[state.postDraft.media[i-1],state.postDraft.media[i]]=[state.postDraft.media[i],state.postDraft.media[i-1]];}else return;renderMediaEditor();renderPreview();save();});
  $('x-post-media-list').addEventListener('input',e=>{const i=e.target.dataset.mediaDuration;if(i===undefined)return;state.postDraft.media[Number(i)].duration=e.target.value;renderPreview();save();});
  $('x-poll-options').addEventListener('input',e=>{if(e.target.dataset.pollChoice!==undefined)state.postDraft.choices[Number(e.target.dataset.pollChoice)].text=e.target.value;else if(e.target.dataset.pollVotes!==undefined)state.postDraft.choices[Number(e.target.dataset.pollVotes)].votes=Math.max(0,Math.min(9999999,Number(e.target.value)||0));renderPreview();save();});
  $('x-poll-options').addEventListener('click',e=>{const b=e.target.closest('[data-remove-choice]');if(!b)return;state.postDraft.choices.splice(Number(b.dataset.removeChoice),1);renderPollEditor();renderPreview();save();});$('x-add-poll-choice').addEventListener('click',()=>{if(state.postDraft.choices.length>=4)return notify('A poll can have up to four choices.');state.postDraft.choices.push({text:'Another option',votes:0});renderPollEditor();renderPreview();save();});
  $('x-screen').addEventListener('click',async e=>{
    const play=e.target.closest('[data-play-media]');if(play){const src=mediaUrls.get(play.dataset.playMedia);if(!src)return notify('The video file is missing. Import its project or attach it again.');const video=document.createElement('video');video.src=src;video.controls=true;video.playsInline=true;video.autoplay=true;play.closest('.xs-media-tile').replaceChildren(video);video.play().catch(()=>{});return;}
    const sensitive=e.target.closest('[data-show-sensitive]');if(sensitive){sensitive.closest('.xs-sensitive').remove();return;}
    const tab=e.target.closest('[data-profile-tab]');if(tab){state.profileTab=tab.dataset.profileTab;renderPreview();save();return;}
    const profileAction=e.target.closest('[data-preview-profile-action]');if(profileAction){const action=profileAction.dataset.previewProfileAction;if(action==='share'){openImage();return;}if(action==='edit'){state.tab='character';syncScene();$('x-character-name').focus();return;}if(action==='follow'){const c=findCharacter(state.selectedCharacter);c.relationship=c.relationship==='not-following'?(c.private?'requested':'following'):'not-following';if(state.characterDraft.id===c.id)state.characterDraft.relationship=c.relationship;syncCharacter();renderPreview();save();return;}notify(action==='notify'?'Profile notification appearance selected.':'Message button selected for this scene.');return;}
    const action=e.target.closest('[data-post-action]');if(action){const p=effectivePost(action.dataset.postId);if(!p)return;const key=action.dataset.postAction;if(key==='heart'||key==='repost'||key==='bookmark'){const field={heart:'liked',repost:'reposted',bookmark:'bookmarked'}[key];p[field]=!p[field];if(state.postDraft.id===p.id)state.postDraft[field]=p[field];const saved=findPost(p.id);if(saved)saved[field]=p[field];syncPost();renderPreview();save();}else if(key==='reply'){state.postDraft={...post(state.selectedCharacter),kind:'reply',reference:p.id};state.selectedPost=state.postDraft.id;state.tab='post';state.view='post';renderAll();save();}else if(key==='share')openImage();else notify(`${p.views||'0'} views · editable in the post editor`);return;}
    if(e.target.closest('[data-open-export]'))return openImage();if(e.target.closest('[data-focus-library]'))return $('x-character-search').focus();if(e.target.closest('[data-go-home-scene]')){state.view='timeline';syncScene();renderPreview();save();return;}if(e.target.closest('[data-go-profile-scene]')){state.view='profile';syncScene();renderPreview();save();return;}
    const nav=e.target.closest('[data-bottom-nav]');if(nav){const name=nav.dataset.bottomNav;if(name==='home'){state.view='timeline';syncScene();renderPreview();save();}else if(name==='search')$('x-character-search').focus();else if(name==='grok')newPost();else notify('Visual navigation for this fictional scene.');}
  });
  const asData=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
  function saveFile(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  $('x-project-save').addEventListener('click',async()=>{try{await persist();const assets={};for(const m of everyMedia()){const blob=mediaBlobs.get(m.id)||await read('media',m.id);if(blob)assets[m.id]=await asData(blob);}saveFile(new Blob([JSON.stringify({format:'draftroom-x',version:1,state,assets})],{type:'application/json'}),'draftroom-x-project.json');notify('Characters, posts and attachments saved in your project.');}catch{notify('Could not save the project. Try again with smaller media.');}});
  $('x-project-import').addEventListener('click',()=>$('x-project-file').click());$('x-project-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(data.format!=='draftroom-x'||!Array.isArray(data.state?.characters)||!data.state.characters.length)throw Error();const next=normalize(data.state);if(!confirm('Import this X project? This replaces only the X studio draft.'))return;for(const [id,uri] of Object.entries(data.assets||{})){if(typeof uri!=='string'||!/^data:(image|video)\//.test(uri))continue;const blob=await(await fetch(uri)).blob();await write('media',id,blob);mediaBlobs.set(id,blob);if(mediaUrls.has(id))URL.revokeObjectURL(mediaUrls.get(id));mediaUrls.set(id,URL.createObjectURL(blob));}state=next;await loadMedia();renderAll();await persist();notify('X project imported.');}catch{notify('Choose a valid Draftroom X project.');}e.target.value='';});
  const dialog=$('x-image-dialog'),imageButtons=[$('x-image-png'),$('x-image-jpg'),$('x-image-copy')];let imageCanvas=null,imageUrl=null;
  const toBlob=(canvas,type='image/png')=>new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Image export failed')),type,.95));
  async function freezeCoverImages(root){for(const image of root.querySelectorAll('.xs-media-tile>img,.xs-profile-banner>img,.xs-avatar>img')){try{await image.decode();const rect=image.getBoundingClientRect();if(!rect.width||!rect.height)continue;const c=document.createElement('canvas');c.width=Math.round(rect.width*2);c.height=Math.round(rect.height*2);const aspect=c.width/c.height;let sw=image.naturalWidth,sh=image.naturalHeight,sx=0,sy=0;if(sw/sh>aspect){sw=sh*aspect;sx=(image.naturalWidth-sw)/2;}else{sh=sw/aspect;sy=(image.naturalHeight-sh)/2;}c.getContext('2d').drawImage(image,sx,sy,sw,sh,0,0,c.width,c.height);image.src=c.toDataURL('image/jpeg',.95);}catch{}}}
  async function capture(mode){await window.DraftroomEmoji?.ready;const scroll=$('x-content-scroll').scrollTop;renderPreview();$('x-content-scroll').scrollTop=scroll;const stage=document.createElement('div');stage.className='xs-capture';stage.style.cssText='position:fixed;left:-20000px;top:0;pointer-events:none;';let target;
    if(mode==='content'){target=document.createElement('div');target.className=`xs-export-content theme-${state.theme}`;const top=$('x-top-navigation').cloneNode(true);top.classList.remove('profile-nav');if(state.view!=='profile')target.append(top);target.append($('x-content').cloneNode(true));}
    else{target=(mode==='phone'?$('x-device'):$('x-screen')).cloneNode(true);target.style.transform='none';target.style.boxShadow='none';if(mode==='screen')target.style.borderRadius='0';}
    stage.append(target);document.body.append(stage);if(mode!=='content')target.querySelector('.xs-content-scroll').scrollTop=scroll;
    try{await document.fonts.ready;await Promise.all([...target.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));await freezeCoverImages(target);return await html2canvas(target,{backgroundColor:null,scale:2,useCORS:true,logging:false,scrollX:0,scrollY:0});}finally{stage.remove();}}
  async function prepareImage(){const generation=++imageGeneration;imageCanvas=null;imageButtons.forEach(b=>b.disabled=true);$('x-image-preview').hidden=true;$('x-image-loading').hidden=false;$('x-image-loading').textContent='Preparing image…';$('x-image-status').textContent='';try{const canvas=await capture($('x-image-layout').value),blob=await toBlob(canvas);if(generation!==imageGeneration||!dialog.open)return;imageCanvas=canvas;if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(blob);$('x-image-preview').src=imageUrl;$('x-image-preview').hidden=false;$('x-image-loading').hidden=true;imageButtons.forEach(b=>b.disabled=false);if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')$('x-image-copy').disabled=true;}catch{$('x-image-loading').textContent='Could not render this scene. Try a smaller project or the content crop.';}}
  function openImage(){$('x-image-layout').value='content';dialog.showModal();prepareImage();}
  for(const id of ['x-export','x-preview-export'])$(id).addEventListener('click',openImage);$('x-image-close').addEventListener('click',()=>dialog.close());$('x-image-layout').addEventListener('change',prepareImage);dialog.addEventListener('close',()=>{imageGeneration++;imageCanvas=null;$('x-image-preview').removeAttribute('src');if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=null;});
  async function download(type){if(!imageCanvas)return;try{let canvas=imageCanvas;if(type==='image/jpeg'){canvas=document.createElement('canvas');canvas.width=imageCanvas.width;canvas.height=imageCanvas.height;const ctx=canvas.getContext('2d');ctx.fillStyle=state.theme==='light'?'#fff':'#000';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(imageCanvas,0,0);}saveFile(await toBlob(canvas,type),`draftroom-x-${state.view}.${type==='image/jpeg'?'jpg':'png'}`);$('x-image-status').textContent='Your picture is saved.';}catch{$('x-image-status').textContent='Could not save. Try right-clicking or holding the preview.';}}
  $('x-image-png').addEventListener('click',()=>download('image/png'));$('x-image-jpg').addEventListener('click',()=>download('image/jpeg'));$('x-image-copy').addEventListener('click',()=>{if(!imageCanvas)return;try{navigator.clipboard.write([new ClipboardItem({'image/png':toBlob(imageCanvas)})]).then(()=>$('x-image-status').textContent='Image copied. Paste it into your story.').catch(()=>$('x-image-status').textContent='Clipboard access was blocked. Save PNG or right-click the picture.');}catch{$('x-image-status').textContent='Copy is unavailable here. Save PNG instead.';}});
  window.addEventListener('pagehide',()=>persist());
  async function init(){db=await openDB();let stored=await read('state','main');if(!stored)try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}if(stored)state=normalize(stored);await loadMedia();ready=true;renderAll();await window.DraftroomEmoji?.ready;renderPreview();}
